'use strict';

/**
* Test whether an input value is a rect mark encoding set.
*
* @module @stdlib/plot/vega/base/assert/is-rect-mark-encoding-set
*
* @example
* var Value = require( '@stdlib/plot/vega/value/ctor' );
* var RectEncodingSet = require( '@stdlib/plot/vega/mark/rect/encoding-set' );
* var isRectMarkEncodingSet = require( '@stdlib/plot/vega/base/assert/is-rect-mark-encoding-set' );
*
* var v = new RectEncodingSet({
*     'x': new Value({
*         'field': 'x',
*         'scale': 'xScale'
*     })
* });
* var bool = isRectMarkEncodingSet( v );
* // returns true
*
* bool = isRectMarkEncodingSet( {} );
* // returns false
*
* bool = isRectMarkEncodingSet( 'foo' );
* // returns false
*/

// MODULES //

var main = require( './main.js' );


// EXPORTS //

module.exports = main;
